  "privacy_policy_our_priority": "আমাদের অগ্রাধিকার",
  "privacy_policy_256_bit": "256-বিট",
  "privacy_policy_eu_standard": "EU মানদণ্ড",
  "privacy_policy_aes_256": "AES-256",
  "privacy_policy_scroll_to_policy": "নীতিমালায় স্ক্রল করুন",
  "privacy_policy_introduction": "ভূমিকা",
  "privacy_policy_paperware_is_committed_to_protecting": "Paperware আপনার গোপনীয়তা রক্ষা এবং ব্যক্তিগত তথ্যের নিরাপত্তা নিশ্চিত করতে প্রতিশ্রুতিবদ্ধ। আপনি যখন আমাদের সেবা, ওয়েবসাইট ব্যবহার করেন বা আমাদের B2B পেপার প্যাকেজিং উৎপাদন প্ল্যাটফর্মের সাথে যুক্ত হন, তখন আমরা কীভাবে আপনার তথ্য সংগ্রহ, ব্যবহার, প্রকাশ ও সুরক্ষিত রাখি, এই গোপনীয়তা নীতিতে তা ব্যাখ্যা করা হয়েছে।",
  "privacy_policy_information_we_collect": "আমরা যে তথ্য সংগ্রহ করি",
  "privacy_policy_we_collect_information_that_you": "আপনি সরাসরি আমাদের যে তথ্য দেন তা আমরা সংগ্রহ করি, যার মধ্যে রয়েছে: ব্যবসায়িক যোগাযোগের তথ্য (নাম, ইমেইল, ফোন, কোম্পানির নাম), অর্ডার ও লেনদেনের তথ্য, পেমেন্ট ও বিলিংয়ের তথ্য, যোগাযোগের পছন্দ এবং আপনি আমাদের প্ল্যাটফর্ম কীভাবে ব্যবহার করেন সে সম্পর্কিত প্রযুক্তিগত তথ্য। B2B ক্লায়েন্টদের ক্ষেত্রে আমরা ব্যবসা নিবন্ধনের নথি ও কর সংক্রান্ত তথ্যও সংগ্রহ করতে পারি।",
  "privacy_policy_how_we_use_your_information": "আপনার তথ্য আমরা যেভাবে ব্যবহার করি",
  "privacy_policy_your_information_is_used_to": "আপনার তথ্য ব্যবহৃত হয় অর্ডার প্রক্রিয়াকরণ, গ্রাহক সহায়তা প্রদান, আমাদের পণ্য ও সেবার উন্নয়ন, গুরুত্বপূর্ণ আপডেট ও (আপনার সম্মতিতে) বিপণন যোগাযোগ পাঠানো, নিরাপত্তা বজায় রাখা ও জালিয়াতি প্রতিরোধ, আইনগত বাধ্যবাধকতা পালন এবং B2B অংশীদারিত্ব ও লেনদেন সহজতর করার জন্য। আমরা কখনোই আপনার ব্যক্তিগত তথ্য তৃতীয় পক্ষের কাছে বিক্রি করি না।",
  "privacy_policy_data_security": "তথ্য নিরাপত্তা",
  "privacy_policy_we_implement_industry_standard_security": "আপনার তথ্য সুরক্ষিত রাখতে আমরা শিল্পমানের নিরাপত্তা ব্যবস্থা গ্রহণ করি, যার মধ্যে রয়েছে এনক্রিপশন, নিরাপদ সার্ভার, অ্যাক্সেস নিয়ন্ত্রণ, নিয়মিত নিরাপত্তা অডিট এবং কর্মীদের প্রশিক্ষণ। তবে ইন্টারনেটের মাধ্যমে তথ্য আদান-প্রদানের কোনো পদ্ধতিই 100% নিরাপদ নয়, তাই আমরা পূর্ণ নিরাপত্তার নিশ্চয়তা দিতে পারি না। নতুন হুমকি মোকাবিলায় আমরা আমাদের নিরাপত্তা চর্চা ক্রমাগত হালনাগাদ করি।",
  "privacy_policy_your_privacy_rights": "আপনার গোপনীয়তার অধিকার",
  "privacy_policy_you_have_the_right_to": "আপনার ব্যক্তিগত তথ্য দেখা, সংশোধন বা মুছে ফেলার অধিকার আপনার রয়েছে। যেকোনো সময় আপনি বিপণন যোগাযোগ থেকে বিরত থাকতে পারেন। আপনার সম্পর্কে আমাদের কাছে থাকা তথ্যের একটি কপি চাইতে পারেন। B2B ক্লায়েন্টরা অ্যাকাউন্ট ড্যাশবোর্ড থেকে ব্যবসার তথ্য হালনাগাদ করতে পারেন। এই অধিকার প্রয়োগ করতে আমাদের গোপনীয়তা দলের সাথে যোগাযোগ করুন।",
  "privacy_policy_cookies_tracking": "কুকি ও ট্র্যাকিং",
